def header(active=""):
    links = [("Esplora", "Esplora"), ("Metodo", "Metodo")]
    nav = "".join(
        f'<a class="{"active" if active == key else ""}" href="#">{label}</a>'
        for key, label in links
    )
    return f"""<div class="topline"><div class="shell"><span>Registro pubblico delle dichiarazioni</span><span>Fonti · tempo · correzioni</span></div></div><header class="header"><div class="shell"><a class="brand"><span class="mark">“</span><b>Dichiarazioni<br>Pubbliche</b></a><nav class="nav">{nav}</nav><div class="head-search">⌕&nbsp;&nbsp;Cerca</div></div></header>"""


def footer():
    return """<footer class="footer"><div class="shell"><div><b>Dichiarazioni Pubbliche</b><div class="hint">La memoria ricercabile di ciò che viene detto in pubblico.</div></div><div class="footlinks"><a>Metodo</a><a>Correzioni</a><a>Dati & API</a><a>Progetto</a><a>Privacy</a></div></div></footer>"""


def page(title, body, active=""):
    return f"""<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{css}</style></head><body>{header(active)}<main>{body}</main>{footer()}</body></html>"""


rows = [
    ("18 set 2026", "Dato numerico", "“Nel trimestre le esportazioni sono cresciute del 6,2%.”", "Marta Rinaldi · Intervista economica", "Supportata", "supported"),
    ("16 set 2026", "Media", "“Questa piattaforma raggiunge ormai un italiano su tre.”", "Luca Berni · Podcast pubblico", "Da contestualizzare", "imprecise"),
    ("14 set 2026", "Politica pubblica", "“Il provvedimento riduce i tempi medi di attesa di trenta giorni.”", "Anna Serra · Conferenza stampa", "Prove insufficienti", "unresolved"),
    ("12 set 2026", "Tecnologia", "“Il nuovo modello consuma la metà delle risorse a parità di risultato.”", "Davide Conti · Video online", "Supportata", "supported"),
]


def claim_rows(explore=False):
    out = []
    for i, (d, t, c, m, s, cl) in enumerate(rows, 1):
        cls = "claimrow explorerow" if explore else "claimrow"
        rank = f'<div class="rank">{i:02}</div>' if explore else ""
        out.append(
            f"""<article class="{cls}">{rank}<div class="date">{d}</div><div><div class="type">{t}</div><a class="claim">{c}</a><div class="meta">{m}</div></div><div class="status {cl}"><span class="dot"></span>{s}</div><div class="arrow">→</div></article>"""
        )
    return "".join(out)


home = f"""<div class="shell"><section class="hero"><div><h1 class="display">La parola lascia una traccia.</h1><p class="lede">La memoria ricercabile di ciò che viene detto in pubblico: parole esatte, fonti, verifiche e cambiamenti nel tempo, senza punteggi alle persone.</p></div><aside class="searchbox"><label>Cerca nel registro</label><div class="search"><input placeholder="Dichiarazione, persona, tema o contenuto…"><button>Cerca</button></div><p class="hint">Ogni risultato mantiene il percorso verso la fonte e la storia delle revisioni.</p></aside></section><section class="section"><div class="sectionhead"><div><h2>Dichiarazioni recenti</h2><p>Un campione trasversale del registro pubblico.</p></div><a class="link">Esplora tutto →</a></div><div class="claimlist">{claim_rows()}</div></section><section class="section"><div class="sectionhead"><div><h2>Dentro una fonte</h2><p>Dal contenuto originale ai momenti pubblicati nel registro.</p></div><a class="link">Apri il contenuto →</a></div><div class="mediafeature"><div class="mediaframe"><span class="time">32:14 / 58:06</span></div><div><h3>Intervista integrale — economia, lavoro e innovazione</h3><p class="lede" style="font-size:17px">Una sola fonte, più dichiarazioni pubblicate. Ogni momento conserva la posizione originale e rimanda alla scheda completa della dichiarazione.</p><div class="moments"><div class="moment"><b>12:42</b><br>dato numerico</div><div class="moment"><b>32:14</b><br>affermazione causale</div><div class="moment"><b>48:03</b><br>confronto storico</div></div></div></div></section></div>"""
(root / "home.html").write_text(page("Home", home), encoding="utf-8")

explore = f"""<div class="shell"><header class="pagehead"><h1>Esplora il registro</h1><p class="lede">Un solo indice per dichiarazioni, persone, temi e contenuti. Parti da una parola e aggiungi filtri solo quando servono.</p></header><div class="toolbar"><div class="search"><input value="innovazione" placeholder="Cerca dichiarazioni, persone, temi, contenuti…"><button>Cerca</button></div><div class="controls"><button class="control">Tutto</button><button class="control">Dichiarazioni</button><button class="control">Persone</button><button class="control">Temi</button><button class="control">Contenuti</button><button class="control">Filtri</button><span class="count">24 risultati</span></div></div><section class="section" style="padding-top:0;border-bottom:0"><div class="claimlist">{claim_rows(True)}{claim_rows(True)}</div></section></div>"""
