statement = f"""<header class="facthead"><div class="shell factgrid"><div><div class="type">Dichiarazione</div><h1 class="claimtitle">“Il nuovo sistema riduce i tempi medi di attesa di trenta giorni.”</h1><div class="factmeta"><b>Anna Serra</b><span>·</span><span>Conferenza stampa del 14 settembre 2026</span><span>·</span><span>18:42–19:21</span></div></div><aside class="factstatus"><small>In breve</small><div class="status unresolved"><span class="dot"></span>Prove insufficienti</div><p class="hint">L’esito riguarda questa dichiarazione, non la persona.</p></aside></div></header><div class="shell factbody"><article class="prose"><p class="answer">I documenti pubblicati confermano una riduzione dei tempi in due strutture, ma non consentono di sostenere che il dato valga per l’intero sistema. <span class="marker">[1]</span></p><h2>Verifica</h2><p>La dichiarazione usa un dato generale. Le evidenze disponibili descrivono campioni parziali e periodi diversi; il confronto non è sufficiente per estendere il risultato a tutto il territorio. <span class="marker">[1]</span> <span class="marker">[2]</span></p><h2>Fonti</h2><a class="sourcerow"><span class="sourceidx">[1]</span><span><b>Ministero competente</b><br><span class="meta">Rapporto trimestrale ufficiale</span></span><span class="date">15 set 2026</span><span>↗</span></a><a class="sourcerow"><span class="sourceidx">[2]</span><span><b>Ufficio statistico nazionale</b><br><span class="meta">Serie storica sui tempi di attesa</span></span><span class="date">10 set 2026</span><span>↗</span></a><h2>Contesto originale</h2><p><a class="link">Apri la conferenza stampa al minuto 18:42 ↗</a></p><h2>Traccia nel tempo</h2><p>Due dichiarazioni revisionate sullo stesso punto mostrano un successivo chiarimento. <a class="link">Apri la traccia →</a></p></article><aside class="rail"><div class="railblock"><small>Fonte originale</small><h3>Conferenza stampa</h3><p class="meta">14 settembre 2026 · video</p></div><div class="railblock"><small>Persona</small><h3>Anna Serra</h3><p class="meta">Responsabile di ente pubblico</p></div><div class="railblock"><small>Versione</small><h3>v1.2</h3><p class="meta">Aggiornata dopo l’aggiunta della fonte [2].</p></div><a class="link">Correzioni e repliche →</a></aside></div>"""
(root / "statement.html").write_text(page("Dichiarazione", statement), encoding="utf-8")

person = f"""<header class="recordhead"><div class="shell recordgrid"><div><div class="type">Persona</div><h1>Livia Ferri</h1><div class="role">Giornalista e conduttrice</div><div class="rolehistory"><span>Televisione · 2022–in corso</span><span>Podcast · 2024–in corso</span></div><p class="recordnote">Questo archivio raccoglie dichiarazioni pubbliche presenti nel registro. Non esiste un punteggio complessivo della persona.</p></div><div class="searchbox" style="border-top:0;padding-top:0"><label>Cerca nell’archivio</label><div class="search"><input placeholder="Parola o tema"><button>Cerca</button></div></div></div></header><div class="shell"><form class="filterbar"><label>Tema<select><option>Tutti</option></select></label><label>Tipo di contenuto<select><option>Tutti</option></select></label><label>Dal<input type="text" value="01/01/2026"></label><label>Al<input type="text" value="03/10/2026"></label><button class="reset">Azzera filtri</button></form><section class="section"><div class="sectionhead"><div><h2>Dichiarazioni</h2><p>In ordine cronologico, con fonte ed esito della singola scheda.</p></div></div><div class="claimlist timeline">{claim_rows()}{claim_rows()}</div></section><section class="section" style="border-bottom:0"><div class="sectionhead"><div><h2>Nel tempo</h2><p>Solo relazioni revisionate che formano una traccia utile.</p></div><a class="link">Apri una traccia →</a></div></section></div>"""
(root / "person.html").write_text(page("Archivio persona", person), encoding="utf-8")

topic = f"""<header class="recordhead"><div class="shell recordgrid"><div><div class="type">Tema</div><h1>Intelligenza artificiale</h1><p class="role">Dossier sulle dichiarazioni pubbliche riguardanti modelli, automazione, lavoro, infrastrutture e policy AI.</p><p class="recordnote">Il dossier descrive ciò che è stato dichiarato e le fonti collegate. Non classifica le persone per posizione politica o affidabilità.</p></div><div class="searchbox" style="border-top:0;padding-top:0"><label>Cerca nel tema</label><div class="search"><input placeholder="Persona, fonte o parola"><button>Cerca</button></div></div></div></header><div class="shell"><section class="section"><div class="sectionhead"><div><h2>Dichiarazioni sul tema</h2><p>Le schede pertinenti al perimetro editoriale approvato.</p></div></div><div class="claimlist">{claim_rows()}</div></section><section class="section"><div class="sectionhead"><div><h2>Tracce nel tempo</h2><p>Aggiornamenti, chiarimenti e relazioni revisionate sullo stesso punto.</p></div><a class="link">Vedi le tracce →</a></div><div class="relationnote"><b>Infrastrutture AI e consumi</b><br>Tre dichiarazioni collegate tra 2025 e 2026, con fonti primarie e aggiornamenti successivi.</div></section><section class="section" style="border-bottom:0"><div class="sectionhead"><div><h2>Contenuti e persone collegate</h2><p>Indici descrittivi per navigare il dossier, senza classifiche.</p></div></div><div class="rolehistory"><span>Interviste</span><span>Audizioni</span><span>Podcast</span><span>Documenti ufficiali</span><span>Esperti</span><span>Imprese</span></div></section></div>"""
(root / "topic.html").write_text(page("Tema", topic), encoding="utf-8")

content = f"""<header class="audithead"><div class="shell"><div class="type">Contenuto · Podcast</div><h1>Intervista integrale — economia, lavoro e innovazione</h1><div class="auditmeta"><span>Podcast pubblico</span><span>·</span><span>18 settembre 2026</span><span>·</span><span>58:06</span><span>·</span><a class="link">Fonte originale ↗</a></div></div></header><div class="shell"><div class="auditlayout"><div><div class="player"><div class="play">▶</div><div class="playercap">32:14 · momento selezionato</div></div><div class="tape"><div class="tick">00:00</div><div class="tick">12:42</div><div class="tick active">32:14</div><div class="tick">48:03</div><div class="tick">58:06</div></div><div class="momentrow"><span class="date">12:42</span><span class="q">“Nel trimestre le esportazioni sono cresciute del 6,2%.”</span><span class="status supported"><span class="dot"></span>Supportata</span></div><div class="momentrow"><span class="date">32:14</span><span class="q">“La misura ha prodotto da sola l’aumento osservato.”</span><span class="status unresolved"><span class="dot"></span>Prove insufficienti</span></div><div class="momentrow"><span class="date">48:03</span><span class="q">“Il livello attuale è il più alto degli ultimi dieci anni.”</span><span class="status imprecise"><span class="dot"></span>Imprecisa</span></div></div><aside class="auditdetail"><small>Momento selezionato · 32:14</small><h2>“La misura ha prodotto da sola l’aumento osservato.”</h2><div class="status unresolved"><span class="dot"></span>Prove insufficienti</div><p>Il contenuto originale mostra il passaggio completo; la scheda della dichiarazione contiene verifica, fonti e cronologia.</p><p style="margin-top:24px"><a class="link">Apri la dichiarazione →</a></p></aside></div></div>"""
(root / "content.html").write_text(page("Contenuto", content), encoding="utf-8")

trace = """<div class="shell"><header class="pagehead"><div class="compareintro"><div class="type">Traccia nel tempo</div><h1>Come è cambiata la previsione sulla data di avvio</h1><p class="lede">Una sequenza revisionata di dichiarazioni sullo stesso punto. La relazione descrive testi, fonti e ordine temporale; non attribuisce intenzioni.</p></div></header><section class="section" style="border-bottom:0"><div class="relationnote"><b>Relazione revisionata: aggiornamento</b><br>Gli esiti restano propri di ciascuna dichiarazione e ogni evento rimanda alla sua fonte.</div><div class="comparetimeline"><article class="event"><div class="eventdate">12 feb<br>2025</div><blockquote>“Il progetto entrerà in funzione entro la fine dell’anno.”</blockquote><div class="eventmeta">Davide Conti · Intervista televisiva · fonte originale disponibile</div><div class="eventstatus status supported"><span class="dot"></span>Supportata nel contesto disponibile</div></article><article class="event"><div class="eventdate">18 set<br>2026</div><blockquote>“La fase operativa partirà nel primo trimestre del prossimo anno.”</blockquote><div class="eventmeta">Davide Conti · Conferenza pubblica · fonte originale disponibile</div><div class="eventstatus status imprecise"><span class="dot"></span>Aggiornamento successivo</div></article><article class="event"><div class="eventdate">02 ott<br>2026</div><blockquote>Correzione pubblicata: la nuova data sostituisce la previsione precedente nel record, che resta consultabile.</blockquote><div class="eventmeta">Nota di aggiornamento · cronologia versionata</div></article></div></section></div>"""
(root / "trace.html").write_text(page("Traccia nel tempo", trace), encoding="utf-8")

method = """<div class="shell method"><article><h1>Una verifica deve poter essere ripercorsa.</h1><p class="methodintro">Dichiarazioni Pubbliche separa acquisizione, evidenza, verifica, revisione e pubblicazione. Una fase completata non autorizza automaticamente la successiva.</p><div class="step"><div class="stepnum">01</div><div><h2>Partire dalle parole esatte</h2><p>Conserviamo formulazione originale, fonte, data e posizione nel contenuto. La normalizzazione aiuta a confrontare i record, ma non sostituisce ciò che è stato detto.</p></div></div><div class="step"><div class="stepnum">02</div><div><h2>Usare fonti adatte alla domanda</h2><p>Preferiamo fonti primarie o ufficiali quando sono autorevoli per la domanda specifica. Ogni evidenza pubblicata mantiene un percorso verificabile verso l’origine.</p></div></div><div class="step"><div class="stepnum">03</div><div><h2>Separare evidenza e valutazione</h2><p>Le prove vengono raccolte e approvate prima della conclusione. Se non bastano, lo stato resta irrisolto o non viene pubblicato.</p></div></div><div class="step"><div class="stepnum">04</div><div><h2>Conservare tempo, correzioni e repliche</h2><p>Una correzione non cancella silenziosamente ciò che c’era prima. Le versioni restano tracciate, con data e motivazione dell’aggiornamento.</p></div></div></article><aside class="principles"><h3>Principi del record</h3><div><b>Nessun punteggio alle persone</b><span>La valutazione appartiene alla singola dichiarazione.</span></div><div><b>Incertezza esplicita</b><span>“Non risolta” e “prove insufficienti” sono risultati legittimi.</span></div><div><b>Fonte a un passo</b><span>Ogni esito pubblico deve poter essere ricondotto alle evidenze approvate.</span></div><div><b>Correzioni versionate</b><span>Gli aggiornamenti aggiungono storia al record, non la cancellano.</span></div></aside></div>"""
(root / "method.html").write_text(page("Metodo", method, "Metodo"), encoding="utf-8")

utility = """<div class="shell method"><article><div class="type">Pagina di fiducia · template condiviso</div><h1>Correzioni, dati e progetto senza creare un altro prodotto.</h1><p class="methodintro">Le pagine di fiducia usano una grammatica documentale comune. Cambiano contenuto e call to action, non il modello di interazione.</p><div class="step"><div class="stepnum">A</div><div><h2>Correzioni</h2><p>Registro cronologico delle modifiche materiali, delle rianalisi e delle repliche pubbliche, con link alla versione interessata.</p></div></div><div class="step"><div class="stepnum">B</div><div><h2>Dati & API</h2><p>Punto di accesso umano a JSON, JSON-LD, OpenAPI, feed, licenze e versioni del contratto pubblico.</p></div></div><div class="step"><div class="stepnum">C</div><div><h2>Progetto</h2><p>Missione, governance, repository open source, indipendenza, responsabilità editoriale e contatti.</p></div></div></article><aside class="principles"><h3>Regola</h3><div><b>Un solo template</b><span>Queste route non giustificano tre nuovi sistemi di pagina.</span></div><div><b>Contribuisci è differito</b><span>La route nasce solo quando i gate anti-abuso e legali sono pronti.</span></div></aside></div>"""
(root / "utility.html").write_text(page("Pagine di fiducia", utility), encoding="utf-8")

canonical = {"home.html", "explore.html", "statement.html", "person.html", "topic.html", "content.html", "trace.html", "method.html", "utility.html"}
for old in root.glob("*.html"):
    if old.name not in canonical:
        old.unlink()

print("built", len(canonical), "canonical mockups")
